209	/**
210	 * Checks if a given file name matches any of the secret file patterns.
211	 */
212	export function isSecretFile(fileName: string): boolean {
213	  return SECRET_FILES.some((s) => {
214	    if (s.pattern.endsWith('*')) {
215	      const prefix = s.pattern.slice(0, -1);
216	      return fileName.startsWith(prefix);
217	    }
218	    return fileName === s.pattern;
219	  });
220	}
